package com.bank.platform.demo;

import java.util.logging.*;

public class PlatformAdvisorDemo {
    private static final Logger log = Logger.getLogger(PlatformAdvisorDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        StreamingPlatformAdvisor advisor = new StreamingPlatformAdvisor();
        PulsarSender pulsar = new PulsarSender();
        KafkaSender kafka = new KafkaSender();

        // Scenario 1 — rapid elastic scaling (festival spike)
        PlatformChoice c1 = advisor.recommend(true, false, false, false);
        log.info(() -> "Scaling spike -> " + c1.getPlatform() + " : " + c1.getReason());

        // Scenario 2 — strict multi-tenancy
        PlatformChoice c2 = advisor.recommend(false, true, false, false);
        log.info(() -> "Multi-tenant -> " + c2.getPlatform() + " : " + c2.getReason());
        pulsar.send("banking-tenant", "payments", "transfers",
                "{\"from\":\"SAV2001\",\"amount\":50000}");

        // Scenario 3 — mixed stream + queue semantics
        PlatformChoice c3 = advisor.recommend(false, false, true, false);
        log.info(() -> "Mixed semantics -> " + c3.getPlatform() + " : " + c3.getReason());

        // Scenario 4 — existing Kafka infra + raw throughput
        PlatformChoice c4 = advisor.recommend(false, false, false, true);
        log.info(() -> "Existing infra -> " + c4.getPlatform() + " : " + c4.getReason());
        kafka.send("trade.feed", "SAV2001", "{\"symbol\":\"RELIANCE\",\"qty\":100}");
    }
}

