class PlatformChoice {
    private final String platform;
    private final String reason;
    PlatformChoice(String platform, String reason) {
        this.platform = platform; this.reason = reason;
    }
    String getPlatform() { return platform; }
    String getReason() { return reason; }
}

// ─── Would be in StreamingPlatformAdvisor.java ───
class StreamingPlatformAdvisor {
    private static final Logger log = Logger.getLogger(StreamingPlatformAdvisor.class.getName());

    PlatformChoice recommend(boolean rapidElasticScaling, boolean multiTenancy,
                             boolean mixedStreamAndQueue, boolean existingKafkaInfra) {
        log.fine(() -> "Evaluating platform: scale=" + rapidElasticScaling
                + " tenant=" + multiTenancy + " mixed=" + mixedStreamAndQueue
                + " kafkaInfra=" + existingKafkaInfra);
        if (existingKafkaInfra) {
            return new PlatformChoice("Kafka",
                "mature ecosystem (Connect/Streams/Schema Registry), existing infra, raw throughput");
        }
        if (rapidElasticScaling) {
            return new PlatformChoice("Pulsar",
                "stateless brokers + BookKeeper storage: add brokers in seconds, no data rebalance");
        }
        if (multiTenancy) {
            return new PlatformChoice("Pulsar",
                "first-class multi-tenancy via tenant/namespace/topic with per-namespace policies");
        }
        if (mixedStreamAndQueue) {
            return new PlatformChoice("Pulsar",
                "Shared/Key_Shared subscriptions give both streaming and queue semantics + DLQ");
        }
        return new PlatformChoice("Kafka",
            "default to mature, well-understood platform when no Pulsar-specific need exists");
    }
}

