class PulsarSender {
    private static final Logger log = Logger.getLogger(PulsarSender.class.getName());
    // Pulsar topic name: persistent://tenant/namespace/topic
    void send(String tenant, String namespace, String topic, String payload) {
        String fqtn = "persistent://" + tenant + "/" + namespace + "/" + topic;
        log.info(() -> "PULSAR produce topic=" + fqtn + " payload=" + payload);
    }
}

