class KafkaSender {
    private static final Logger log = Logger.getLogger(KafkaSender.class.getName());
    // Kafka topic name is flat; broker owns the partition storage
    void send(String topic, String key, String payload) {
        log.info(() -> "KAFKA produce topic=" + topic + " key=" + key + " payload=" + payload);
    }
}

